using System;using System.IO;using System.Linq;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;
partial class UsageWidget {
 void SetupFixtures(){states.Clear();for(int i=0;i<2;i++){var data=new Snapshot{ShortUsed=i==0?40:58,WeekUsed=i==0?32:76,ShortReset=DateTimeOffset.Now.AddMinutes(i==0?227:147).ToUnixTimeSeconds(),WeekReset=DateTimeOffset.Now.AddHours(i==0?74:60).ToUnixTimeSeconds(),Updated=DateTime.Now,TodayLocalTokens=i==0?42100:17000,AccountId="SYNTHETIC_ACCOUNT_"+i};data.DailyTokens[DailyUsageView.DateKey(DateTime.Today.AddDays(-1))]=2900000;data.DailyTokens[DailyUsageView.DateKey(DateTime.Today.AddDays(-2))]=0;states.Add(new AccountState{Entry=new AccountEntry{Id="fixture-"+i,Alias=i==0?"개인":"업무",Kind="managed"},Data=data,Connected=true});}selectedId=miniId=states[0].Entry.Id;}
 void CapturePreview(string file){if(AppPaths.Report==null)return;using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(Point.Empty,Size));bmp.Save(Path.Combine(AppPaths.Report,file));}}
 async Task VerifyBoard(){bool full=fullEnabled,mini=miniEnabled,pinned=TopMost;string mode=themeMode;
  themeMode="light";ApplyTheme();CapturePreview("board-light.png");themeMode="dark";ApplyTheme();CapturePreview("board-dark.png");SelectTab("기록");CapturePreview("history.png");SelectTab("설정");CapturePreview("settings.png");SelectTab("한도");
  SetMini(true);ShowFull(true);await Task.Delay(350);bool both=Visible&&miniWindow.Visible;ShowFull(false);bool miniOnly=!Visible&&miniWindow.Visible;SetMini(false);bool neither=!Visible&&!miniWindow.Visible&&tray.Visible;ShowFull(true);bool fullOnly=Visible&&!miniWindow.Visible;
  TopMost=!pinned;ApplyTheme();bool pinChanged=pin.Text.Contains(TopMost?"ON":"OFF");TopMost=pinned;
  SetMini(true);await Task.Delay(300);SendMessage(miniWindow.Handle,0x200,System.IntPtr.Zero,System.IntPtr.Zero);bool hover=miniWindow.Hovered;using(var bmp=new Bitmap(miniWindow.Width,miniWindow.Height)){miniWindow.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(Path.Combine(AppPaths.Report,"taskbar-mini.png"));}SendMessage(miniWindow.Handle,0x2A3,System.IntPtr.Zero,System.IntPtr.Zero);bool hoverLeaves=!miniWindow.Hovered;
  bool common=Object.ReferenceEquals(shared,miniWindow.ContextMenuStrip);BuildMenu();bool updateMenu=shared.Items.Cast<ToolStripItem>().Any(x=>x.Text.StartsWith("업데이트 확인"));bool accountMenu=shared.Items.Cast<ToolStripItem>().Any(x=>x.Text=="미니바 계정");
  string menuCloseReason="";ToolStripDropDownClosedEventHandler closedMenu=delegate(object sender,ToolStripDropDownClosedEventArgs e){menuCloseReason=e.CloseReason.ToString();};shared.Closed+=closedMenu;SendMessage(miniWindow.Handle,0x200,System.IntPtr.Zero,System.IntPtr.Zero);miniWindow.OpenMenu(new Point(miniWindow.Bounds.Left,miniWindow.Bounds.Top));bool menuOpened=shared.Visible;SendMessage(miniWindow.Handle,0x2A3,System.IntPtr.Zero,System.IntPtr.Zero);await Task.Delay(250);bool menuAfterLeave=shared.Visible;for(int i=0;i<3;i++){UpdateMini();await Task.Delay(450);}bool menuAfterRefresh=shared.Visible;shared.Closed-=closedMenu;shared.Close();
  bool featuresPassed=await VerifyNewFeatures();for(int i=0;i<12&&!miniWindow.ReceivesPointer;i++)await Task.Delay(150);
  SafeJson.Write(Path.Combine(AppPaths.Report,"ui-verification.json"),new{version=BuildInfo.Version,synthetic=true,twoAccounts=states.Count==2,both=both,miniOnly=miniOnly,neither=neither,fullOnly=fullOnly,pinChanged=pinChanged,sharedMenu=common,hover=hover&&hoverLeaves,updateMenu=updateMenu,accountMenu=accountMenu,defaultDark=mode=="dark",featuresPassed=featuresPassed,menuOpened=menuOpened,menuAfterLeave=menuAfterLeave,menuAfterRefresh=menuAfterRefresh,menuCloseReason=menuCloseReason,taskbarEmbedded=miniWindow.Embedded,taskbarFramePresented=miniWindow.FramePresented,taskbarReceivesPointer=miniWindow.ReceivesPointer,pointerTarget=miniWindow.PointerTarget,miniBounds=miniWindow.Bounds,taskbarBounds=miniWindow.TaskbarBounds,taskbarError=miniWindow.LastError,missingZero=DailyUsageView.CheckMissingAndZero(),countdown=ResetCountdown.CheckBoundaries()});
  themeMode=mode;miniEnabled=mini;fullEnabled=full;SaveSettings();exitRequested=true;Close();
 }
 void WriteVerification(){if(AppPaths.Report==null)return;CapturePreview("live-preview.png");SafeJson.Write(Path.Combine(AppPaths.Report,"verification.json"),new{version=BuildInfo.Version,live=states.Any(s=>s.Connected&&s.Data!=null&&s.Error==null),accountCount=states.Count,connectedCount=states.Count(s=>s.Connected),errors=states.Where(s=>s.Error!=null).Select(s=>s.Error).ToArray(),mini=miniWindow.Embedded,frame=miniWindow.FramePresented});}
